~~~go
func areAnagrams(a, b string) bool {
    counts := make(map[rune]int)
    for _, r := range a { counts[r]++ }
    for _, r := range b {
        if counts[r] == 0 { return false }
        counts[r]--
    }
    for _, n := range counts { if n != 0 { return false } }
    return true
}
~~~

